package com.creditsense.security;
import com.creditsense.domain.User; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*;
@Service public class JwtService { private final SecretKey key; public JwtService(@Value("${jwt.secret}") String secret){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String issue(User u){return Jwts.builder().subject(u.getId().toString()).claim("role",u.getRole().name()).claim("email",u.getEmail()).issuedAt(Date.from(Instant.now())).expiration(Date.from(Instant.now().plusSeconds(900))).signWith(key).compact();} public UUID subject(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());} }
